queries.mql:
select all objects where
[verse
  [word FOCUS
    lex_utf8 = "טף"
  ]
]

select all objects where
[verse
  [unorderedgroup
    [word FOCUS
      lex_utf8 = "טף"
    ]
    [word FOCUS
      lex_utf8 = "אישׁ" or lex_utf8 = "אשׁה" or lex_utf8 = "גר"
    ]
  ]
]

select all objects where
[verse
  [unorderedgroup
    [word FOCUS
      lex_utf8 = "טף"
    ]
    [word FOCUS
      lex_utf8 = "אישׁ" 
    ]
    [word FOCUS
      lex_utf8 = "אשׁה"
    ]
    [word FOCUS
      lex_utf8 = "גר"
    ]
  ]
]
